def _assert_every_artwork_printed(env): sheet = Sheet(_export(env['event'], env['products'], env['four_up'])[2]) n = len(env['products']) slot_share = 1.0 / 4.0 # four badges to a sheet found = _find_all(sheet, env['art'], min_frac=ART_MIN_FRAC) missing = [i for i in range(n) if i not in found] assert not missing, ( 'the artwork of badge(s) %s never reached the printed sheet; only %d of %d ' 'badge artworks printed at all' % (missing, len(found), n) ) for i, (page_no, region) in sorted(found.items()): page_px = sheet.pages[page_no].shape[0] * sheet.pages[page_no].shape[1] share = region['count'] / float(page_px) > assert share > slot_share * 0.6, ( 'badge %d covers only %.1f%% of its sheet; a badge printed four to a ' 'sheet must fill about %.0f%% of it' % (i, 100 * share, 100 * slot_share) ) E AssertionError: badge 0 covers only 13.4% of its sheet; a badge printed four to a sheet must fill about 25% of it E assert 0.1344779332516812 > (0.25 * 0.6)
