sp, sr = sheet_art[i] slot = _box(sr) slot_w = float(slot[2] - slot[0]) slot_h = float(slot[3] - slot[1]) ink_box = _box(sheet_ink[i][1]) got = ( ((ink_box[0] + ink_box[2]) / 2.0 - slot[0]) / slot_w, ((ink_box[1] + ink_box[3]) / 2.0 - slot[1]) / slot_h, ) > assert abs(got[0] - want[0]) < 0.05 and abs(got[1] - want[1]) < 0.05, ( 'badge %d prints its text at %s of its slot on the shared sheet but at ' '%s of the sheet when printed on its own' % (i, got, want) ) E AssertionError: badge 0 prints its text at (0.4991935483870968, 0.6548387096774193) of its slot on the shared sheet but at (0.49838969404186795, 0.4629418472063854) of the sheet when printed on its own E assert (0.0008038543452288383 < 0.05 and 0.19189686247103388 < 0.05) E + where 0.0008038543452288383 = abs((0.4991935483870968 - 0.49838969404186795)) E + and 0.19189686247103388 = abs((0.6548387096774193 - 0.4629418472063854))
