env = {'event': <Event: Badge print nordkap>, 'products': [<Product: render_nup ticket 0>, <Product: merge_foreground_buffer...00), (140, 200, 40)], 'ink': [(100, 0, 50), (0, 100, 50), (50, 0, 100), (100, 50, 0), (0, 50, 100), (50, 100, 0)], ...} rendering = 'a4_a6p', grid = (2, 2)
def _assert_layout_is_a_regular_grid(env, rendering, grid): """Badges must be laid out on the grid the rendering option describes.""" cols, rows = grid sheet = Sheet(_export(env['event'], env['products'], rendering)[2]) per_page = cols * rows n = len(env['products'])
marks = _find_all(sheet, env['ink'], min_count=MIN_MARK_PX) missing = [i for i in range(n) if i not in marks] assert not missing, ( 'badge(s) %s printed nothing readable on the %d-up sheet -- their content ' 'fell outside the printable area' % (missing, per_page) )
by_page = {} for i, (page_no, region) in marks.items(): by_page.setdefault(page_no, []).append((i, _centre(region)))
for page_no, entries in by_page.items(): page = sheet.pages[page_no] height_px, width_px = page.shape[0], page.shape[1] cell_w = width_px / float(cols) cell_h = height_px / float(rows) tol = 0.04 * min(cell_w, cell_h) ref = entries[0][1] for i, centre in entries[1:]: for axis, pitch, name in ((0, cell_w, 'across'), (1, cell_h, 'down')): delta = centre[axis] - ref[axis] steps = round(delta / pitch) > assert abs(delta - steps * pitch) <= tol, ( 'badge %d sits %.1f px %s from badge %d on sheet page %d, which ' 'is not a whole number of %.1f px slots' % (i, delta, name, entries[0][0], page_no, pitch) ) E AssertionError: badge 2 sits 620.0 px down from badge 0 on sheet page 0, which is not a whole number of 877.0 px slots E assert 257.0 <= 24.82 E + where 257.0 = abs((620.0 - (1 * 877.0)))
